<script setup lang="ts">import type {Run} from '../types/domain';import {dec} from '../utils/format';defineProps<{run:Run}>()</script><template><div class="run-summary"><div><small>预先选择 K</small><b>{{run.config.k}}</b></div><div><small>真实初始化重复</small><b>{{run.config.repeats}}</b></div><div><small>原篇 / 有效组 / 词汇</small><b>{{run.result.original_documents??run.result.effective_documents??'—'}}<span> / {{run.result.effective_groups??run.result.effective_documents??'—'}} / {{run.result.vocabulary?.length??'—'}}</span></b></div><div><small>独立组 / 排除原文</small><b>{{run.result.deduplication?.group_count??run.result.group_count??run.result.effective_documents??'—'}}<span> / {{run.result.excluded_documents?.length??'—'}}</span></b></div><div><small>参照对齐平均余弦</small><b>{{dec(run.result.mean_alignment_similarity)}}</b></div></div></template>
